<?php
namespace Tests\Feature;
use App\Models\{Group,MediaAsset,User};use App\Services\Media\MediaVariantProcessor;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Http\UploadedFile;use Illuminate\Support\Facades\{Hash,Queue,Storage};use Tests\TestCase;
class UploadQualityModeTest extends TestCase {use RefreshDatabase;protected function setUp():void{parent::setUp();config(['media.disk'=>'private_local','queue.default'=>'sync']);Storage::fake('private_local');Queue::fake();}private function owner(string$quality='standard'):array{$u=User::create(['name'=>'Owner','email'=>'quality@test.local','password'=>Hash::make('x'),'status'=>'active','meta'=>['preferences'=>['upload_quality_preference'=>$quality,'post_transfer_action'=>'none']]]);$g=Group::create(['name'=>'Gallery','creator_id'=>$u->id,'downloads_enabled'=>true]);$g->members()->attach($u->id,['role'=>'admin','membership_status'=>'active','access_type'=>'full_access']);return[$u,$g];}private function jpeg():UploadedFile{$path=tempnam(sys_get_temp_dir(),'quality-');$image=imagecreatetruecolor(1800,1200);for($y=0;$y<1200;$y+=20){$color=imagecolorallocate($image,$y%255,($y*2)%255,($y*3)%255);imagefilledrectangle($image,0,$y,1799,$y+19,$color);}imagejpeg($image,$path,100);imagedestroy($image);return new UploadedFile($path,'portrait-session.jpg','image/jpeg',null,true);}public function test_standard_preference_classifies_future_upload_and_ignores_browser_override():void{[$u,$g]=$this->owner();$this->actingAs($u)->postJson(route('photos.store',$g),['quality_mode'=>'high_resolution','photos'=>[$this->jpeg()]])->assertOk();$asset=MediaAsset::firstOrFail();$this->assertSame('standard',$asset->quality_mode);$this->assertSame('1.00',$asset->quota_units);$this->assertSame('1.00',\App\Models\MediaQuotaUsageEvent::firstOrFail()->quantity);}public function test_high_resolution_preference_consumes_exactly_two_and_a_half_units():void{[$u,$g]=$this->owner('high_resolution');$this->actingAs($u)->postJson(route('photos.store',$g),['quality_mode'=>'standard','photos'=>[$this->jpeg()]])->assertOk();$asset=MediaAsset::firstOrFail();$this->assertSame('high_resolution',$asset->quality_mode);$this->assertSame('2.50',$asset->quota_units);$this->assertSame('2.50',\App\Models\MediaQuotaUsageEvent::firstOrFail()->quantity);$this->assertSame(2.5,app(\App\Services\Storage\StorageUsage::class)->summary($u)['used_quota_units']);}}
